  Lemma pf_case : forall dirs ss' scs scr' kn' hs',
    sym_exec RSEGS pf_fuel true pf_stops (SCR dirs [] []) (SS 0x3499c pf_sr [] pf_kn 40) [] = (ss', scs, scr') ->
    s_pc ss' = 0x348f0 ->
    log_covered pf_regions (s_log ss') = true ->
